<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {Layers3,ArrowUpRight,Copy,Download,Menu,X} from 'lucide-vue-next'
import {api,copy,action,type Row} from '../lib'
const spec=ref<Row>({}),error=ref(''),lang=ref('curl'),mobile=ref(false),origin=location.origin
const operations=computed(()=>Object.entries(spec.value.paths||{}).flatMap(([path,v])=>Object.entries(v as Row).map(([method,op])=>({path,method,op,id:(op as Row).operationId}))))
const states:Row={draft:'已保存',queued:'等待调度',processing:'正在办理',awaiting_payment:'结账链接已生成，未付款',succeeded:'付款已完成，继续查看订阅和续费结果',failed:'办理未完成',cancelled:'已停止',review:'结果待核实，停止重复提交'}
function schema(v:Row):Row{return v?.$ref?{...spec.value.components?.schemas?.[v.$ref.split('/').at(-1)],...v}:v||{}}
function fields(v:Row,prefix=''):Row[]{const s=schema(v);return Object.entries(s.properties||{}).flatMap(([key,value])=>{const f=value as Row,name=prefix+key,row={...schema(f),...f,name,required:s.required?.includes(key),nested:!!prefix};const children=f.properties?fields(f,name+'.'):f.items?.properties?fields(f.items,name+'[].'):[];return [row,...children]})}
function type(v:Row){if(v.anyOf)return v.anyOf.map((x:Row)=>type(x)).join(' / ');return v.$ref?v.$ref.split('/').at(-1):v.const!==undefined?JSON.stringify(v.const):v.enum?v.enum.join(' / '):Array.isArray(v.type)?v.type.join(' / '):v.type||'object'}
function sample(x:Row){const body=x.op.requestBody?.content?.['application/json']?.example;let url=origin+x.path.replace('{id}','ORDER_ID');const query=(x.op.parameters||[]).filter((p:Row)=>p.in==='query'&&p.required);if(query.length)url+='?'+query.map((p:Row)=>p.name+'='+encodeURIComponent(p.example||'VALUE')).join('&');const headers:Row={Authorization:'Bearer YOUR_API_KEY'};if(body)headers['Content-Type']='application/json';if(lang.value==='python')return `import os\nimport json\nimport requests\n\nheaders = ${JSON.stringify(headers,null,2).replace('"Bearer YOUR_API_KEY"','"Bearer " + os.environ["XUFU_API_KEY"]')}\n${body?'payload = '+'json.loads('+JSON.stringify(JSON.stringify(body))+')'+'\n':''}response = requests.${x.method}(\n    ${JSON.stringify(url)}, headers=headers, ${body?'json=payload, ':''}timeout=30\n)\nresponse.raise_for_status()\nprint(response.json())`;if(lang.value==='node')return `const response = await fetch(${JSON.stringify(url)}, {\n  method: ${JSON.stringify(x.method.toUpperCase())},\n  headers: ${JSON.stringify(headers,null,2).replace('"Bearer YOUR_API_KEY"','"Bearer " + process.env.XUFU_API_KEY')}${body?',\n  body: JSON.stringify('+JSON.stringify(body,null,2)+')':''}\n});\nconst result = await response.json();\nif (!response.ok) throw new Error(result.error);\nconsole.log(result);`;return `curl --fail-with-body '${url}' \\\n  -X ${x.method.toUpperCase()} \\\n  `+Object.entries(headers).map(([k,v])=>`-H '${k}: ${v}'`).join(' \\\n  ')+(body?` \\\n  -d '${JSON.stringify(body,null,2)}'`:'')}
onMounted(async()=>{try{spec.value=await api('/openapi.json')}catch(e){error.value=(e as Error).message}})
</script>
<template><div class="api-docs"><button class="docs-menu-toggle icon-btn bordered" @click="mobile=!mobile" aria-label="文档菜单"><Menu :size="20"/></button><aside class="docs-sidebar" :class="{open:mobile}"><a href="/#/home" class="brand"><span class="brand-icon"><Layers3 :size="23"/></span><b>序付<small>DEVELOPERS</small></b></a><button class="icon-btn docs-close" @click="mobile=false" aria-label="收起文档菜单"><X/></button><p class="eyebrow">接入指引</p><a href="/docs#start" @click="mobile=false">快速开始</a><a href="/docs#auth" @click="mobile=false">鉴权与安全</a><a href="/docs#results" @click="mobile=false">订单结果判断</a><p class="eyebrow">平台 API</p><a v-for="x in operations" :key="x.id" :href="'/docs#'+x.id" @click="mobile=false"><span :class="['method',x.method]">{{x.method.toUpperCase()}}</span>{{x.op.summary}}</a><p class="eyebrow">参考</p><a href="/docs#fields" @click="mobile=false">Session 与订单字段</a><a href="/docs#states" @click="mobile=false">状态与重试</a><a href="/docs#errors" @click="mobile=false">错误处理</a><a href="/api/openapi.json" download="xufupython-openapi.json"><Download :size="14"/>OpenAPI 3.1</a><a href="/#/keys">返回开发接入<ArrowUpRight :size="14"/></a></aside><main class="docs-main"><div v-if="error" class="alert danger">{{error}}</div><section id="start" class="docs-intro"><span class="eyebrow">序付 API</span><h1>API 接入文档</h1><p>查询余额、会员、套餐、报价与订单，检查账号 Session，以及兑换余额。</p><div class="docs-base"><code>{{origin}}</code><button class="text-btn" @click="action(()=>copy(origin))"><Copy :size="15"/>复制基础地址</button></div><div class="callout">订阅办理、生成结账链接和关闭续费请在网页操作。API 可查询已提交订单的进度与结果。</div><div class="docs-steps"><span>01 创建 API 密钥</span><span>02 查询报价与余额</span><span>03 调用所需接口</span><span>04 按返回状态处理结果</span></div></section><section id="auth" class="panel docs-section"><h2>鉴权与数据约定</h2><p>本文业务接口均要求 <code>Authorization: Bearer YOUR_API_KEY</code>。密钥只能访问所属账户的数据。密钥仅创建时显示一次，撤销后立即失效。</p><p>余额与服务费以分 R 计价，100 分 R = 1 R；可用余额为 balance − frozen。银行卡金额使用对应币种的最小单位：JPY 为日元，其余支持币种除以 100 展示。</p><p>请从你的服务端调用，不把密钥、兑换码、Session 或银行卡放在 URL 和日志里。当前不开放跨域浏览器调用；不要在浏览器前端嵌入长期 API 密钥。</p><p>遇到 HTTP 429 时降低请求频率，等待后重试。</p></section>
<section id="results" class="panel docs-section"><h2>订单结果判断</h2><p>订阅与结账链接在网页提交后，可使用订单接口查询进度。生成链接的订单到达 <code>awaiting_payment</code> 后，从 <code>checkout.url</code> 取得地址即可。</p><div class="docs-table"><table><thead><tr><th>结果</th><th>确认字段</th></tr></thead><tbody><tr><td>付款成功</td><td><code>payment.state = succeeded</code></td></tr><tr><td>订阅生效</td><td><code>order.activation = active</code></td></tr><tr><td>自动续费关闭</td><td><code>order.renewal = disabled</code>；kept 表示按要求保留。</td></tr></tbody></table></div><p>付款成功但生效或续费仍待核实时，联系服务支持处理原订单，不要重复付款。HTTP 200 只表示查询成功。</p></section>
<section v-for="x in operations" :key="x.id" :id="x.id" class="panel docs-section"><div class="endpoint"><b :class="x.method">{{x.method.toUpperCase()}}</b><code>{{x.path}}</code></div><h2>{{x.op.summary}}</h2><p>{{x.op.description}}</p><div v-if="x.op.parameters?.length" class="docs-table"><table><thead><tr><th>参数</th><th>位置</th><th>要求</th><th>说明</th></tr></thead><tbody><tr v-for="p in x.op.parameters" :key="p.name"><td><code>{{p.name}}</code></td><td>{{p.in}}</td><td>{{p.required?'必填':'可选'}}</td><td>{{p.description||p.example||''}} {{p.schema.minLength?'长度 '+p.schema.minLength+'～'+p.schema.maxLength:''}}</td></tr></tbody></table></div><div v-if="x.op.requestBody" class="docs-table"><table><thead><tr><th>JSON 字段</th><th>类型</th><th>要求</th><th>说明</th></tr></thead><tbody><tr v-for="f in fields(x.op.requestBody.content['application/json'].schema)" :key="f.name"><td><code>{{f.name}}</code></td><td>{{type(f)}}</td><td>{{f.required?(f.nested?'提供父字段时必填':'必填'):'可选'}}</td><td>{{f.description||'详见下方字段说明'}}</td></tr></tbody></table></div><div class="section-heading"><div class="tabs"><button v-for="l in ['curl','node','python']" :key="l" :class="{active:lang===l}" @click="lang=l">{{({curl:'cURL',node:'Node.js',python:'Python'} as Row)[l]}}</button></div><button class="text-btn" @click="action(()=>copy(sample(x)))"><Copy :size="14"/>复制示例</button></div><pre>{{sample(x)}}</pre><details><summary>查看响应字段和示例</summary><div v-for="(response,code) in x.op.responses" :key="code"><h4>HTTP {{code}} · {{(response as Row).description}}</h4><div class="docs-table" v-if="fields((response as Row).content?.['application/json']?.schema).length"><table><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr v-for="f in fields((response as Row).content?.['application/json']?.schema)" :key="f.name"><td>{{f.name}}</td><td>{{type(f)}}</td><td>{{f.description||'详见完整字段说明'}}</td></tr></tbody></table></div></div><pre>{{JSON.stringify((x.op.responses['200']||x.op.responses['202'])?.content?.['application/json']?.example||{},null,2)}}</pre></details></section>
<section id="fields" class="panel docs-section"><h2>完整字段说明</h2><p>字段名中的点表示嵌套对象，[] 表示数组元素；引用类型可在本节展开对应名称查看。</p><p>Session 示例中的令牌仅为占位符，请使用账号最新的完整 Session。检查接口只校验格式、账号信息与有效期，不代表订阅已生效。</p><details v-for="(s,name) in spec.components?.schemas" :key="name"><summary>{{name}}</summary><div class="docs-table"><table><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr v-for="f in fields(s)" :key="f.name"><td>{{f.name}}</td><td>{{type(f)}}</td><td>{{f.description||'—'}}</td></tr></tbody></table></div></details></section><section id="states" class="panel docs-section"><h2>订单状态与重试</h2><div class="docs-table"><table><tbody><tr v-for="(label,state) in states" :key="state"><td><code>{{state}}</code></td><td>{{label}}</td></tr></tbody></table></div><p>排队或办理中的订单建议每 5 秒查询一次。生成链接的订单到达 awaiting_payment 后可停止轮询。付款成功但生效或续费待核实时，请联系服务支持处理原订单。</p></section><section id="errors" class="panel docs-section"><h2>错误状态</h2><p>失败返回 <code>{"error":"中文错误原因"}</code>，按 HTTP 状态处理，不依赖中文文案进行分支判断。</p><div class="docs-table"><table><tbody><tr v-for="(v,k) in {400:'检查参数、Session 有效期或兑换码状态',401:'重新创建有效密钥，确认账户可用',403:'密钥没有相应权限，或请求来源不被允许',404:'订单不存在或不属于当前账户',429:'降低请求频率，等待后重试',500:'稍后重试查询；兑换超时先核对余额'}" :key="k"><td><code>{{k}}</code></td><td>{{v}}</td></tr></tbody></table></div></section></main></div></template>
